<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { RouterLink } from 'vue-router'
import { api, ApiError } from '../../api/client'
import AppIcon from '../../components/AppIcon.vue'
type Claim={id:string;item_title:string;status:string;submitted_at:string;updated_at:string;viewer_role:string;allowed_actions:string[]}
const claims=ref<Claim[]>([]);const filter=ref('ALL');const loading=ref(true);const error=ref('')
const visible=computed(()=>filter.value==='ALL'?claims.value:claims.value.filter(entry=>entry.status===filter.value))
onMounted(async()=>{try{const response=await api<{data:{items:Claim[]}}>('/claims/?page_size=100');claims.value=response.data.items}catch(reason){error.value=reason instanceof ApiError?reason.message:'无法读取认领记录'}finally{loading.value=false}})
</script>
<template><div class="page"><header><h1 class="page-title">认领记录</h1></header><div class="tabs"><button v-for="entry in [['ALL','全部'],['SUBMITTED','待核对'],['NEEDS_INFO','待补充'],['APPROVED','已通过'],['HANDOVER_PENDING','待交接'],['COMPLETED','已完成']]" :key="entry[0]" :class="{active:filter===entry[0]}" @click="filter=entry[0]">{{entry[1]}}</button></div><p v-if="loading" class="empty">正在读取…</p><p v-else-if="error" class="empty error">{{error}}</p><div v-else-if="visible.length" class="claim-list"><RouterLink v-for="claim in visible" :key="claim.id" :to="`/claims/${claim.id}`" class="panel claim"><span class="status-tag">{{claim.viewer_role==='CLAIMANT'?'我的申请':'收到的申请'}}</span><div><h2>{{claim.item_title}}</h2><p>{{new Date(claim.updated_at).toLocaleString('zh-CN')}}</p></div><span v-if="claim.allowed_actions.length" class="todo">待处理</span><AppIcon name="arrow"/></RouterLink></div><div v-else class="empty"><AppIcon name="shield"/><h2>当前没有记录</h2><RouterLink to="/found" class="button button-brand">浏览招领线索</RouterLink></div></div></template>
<style scoped>.tabs{display:flex;gap:7px;overflow:auto;margin:32px 0 20px}.tabs button{white-space:nowrap;padding:10px 14px;color:var(--ct-text-muted);border:1px solid var(--ct-border);border-radius:10px;background:transparent}.tabs button.active{color:var(--ct-brand-ink);background:var(--ct-brand)}.claim-list{display:grid;gap:10px}.claim{display:grid;grid-template-columns:auto 1fr auto auto;gap:18px;align-items:center;padding:19px;box-shadow:none}.claim h2,.claim p{margin:0}.claim p{margin-top:5px;color:var(--ct-text-muted);font-size:12px}.todo{color:var(--ct-brand);font-size:12px}.empty{display:grid;place-items:center;gap:12px;min-height:280px;color:var(--ct-text-muted);border:1px dashed var(--ct-border);border-radius:16px}.error{color:var(--ct-danger)}@media(max-width:650px){.claim{grid-template-columns:auto 1fr}.claim>.todo,.claim>svg{grid-column:2}}</style>
